WITH ranked AS (SELECT id, full_name, dept_id, job_title, is_remote FROM (SELECT *, RANK() OVER (PARTITION BY manager_id ORDER BY hire_date DESC) AS row_num FROM employees) ranked WHERE row_num = 1) SELECT dept_id, COUNT(*) FILTER (WHERE job_title = 'Designer') AS designer_rows, COUNT(DISTINCT job_title) AS distinct_job_titles, SIZE(COLLECT_SET(job_title)) AS num_job_titles, COUNT(CASE WHEN job_title = 'Intern' THEN 1 END) AS intern_count FROM ranked GROUP BY dept_id
